'use client';

import { useEffect, useRef, useState } from 'react';

const DETECTION_BOXES = [
  { id: 1, top: '35%', left: '15%', width: '22%', height: '28%', label: 'NO PLATE DETECTED', type: 'alert' },
  { id: 2, top: '40%', left: '58%', width: '18%', height: '24%', label: 'VEHICLE TRACKED', type: 'green' },
];

export default function LiveMonitor({ stream, isActive }) {
  const videoRef = useRef(null);
  const [time, setTime] = useState('');
  const [showBoxes, setShowBoxes] = useState(false);
  const [scanLine, setScanLine] = useState(0);

  useEffect(() => {
    const tick = () => {
      const now = new Date();
      setTime(now.toLocaleTimeString('en-GB', { hour12: false }) + '.' + String(now.getMilliseconds()).padStart(3, '0').slice(0, 2));
    };
    tick();
    const iv = setInterval(tick, 100);
    return () => clearInterval(iv);
  }, []);

  useEffect(() => {
    if (videoRef.current) {
      if (stream) {
        videoRef.current.srcObject = stream;
        videoRef.current.play().catch(() => {});
        setTimeout(() => setShowBoxes(true), 1500);
      } else {
        videoRef.current.srcObject = null;
        setShowBoxes(false);
      }
    }
  }, [stream]);

  // Animate scan line
  useEffect(() => {
    if (!isActive) return;
    let pos = 0;
    const iv = setInterval(() => {
      pos = (pos + 1) % 100;
      setScanLine(pos);
    }, 20);
    return () => clearInterval(iv);
  }, [isActive]);

  return (
    <div className="panel" style={{ height: '100%' }}>
      <div className="panel-header">
        <span className="panel-title">Live CCTV Monitor</span>
        <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
          {isActive && (
            <div className="hud-rec" style={{ fontSize: '10px' }}>
              <div className="rec-dot" />
              REC
            </div>
          )}
          <span
            className="panel-badge"
            style={{
              background: 'rgba(6,182,212,0.1)',
              color: '#06b6d4',
              border: '1px solid rgba(6,182,212,0.25)',
            }}
          >
            CAM-01 / MAIN
          </span>
        </div>
      </div>

      <div className="panel-body" style={{ padding: '16px', display: 'flex', flexDirection: 'column', gap: '16px' }}>
        {/* Monitor */}
        <div className="monitor-container">
          {/* Grid overlay */}
          <div className="monitor-grid-overlay" />

          {/* Corner brackets */}
          <div className="monitor-corner tl" />
          <div className="monitor-corner tr" />
          <div className="monitor-corner bl" />
          <div className="monitor-corner br" />

          {/* Video */}
          <video
            ref={videoRef}
            muted
            autoPlay
            playsInline
            style={{ display: isActive ? 'block' : 'none' }}
          />

          {/* Placeholder when not active */}
          {!isActive && (
            <div className="monitor-placeholder">
              <div style={{ position: 'relative', zIndex: 1 }}>
                <svg width="56" height="56" viewBox="0 0 56 56" fill="none">
                  <rect width="56" height="56" rx="10" fill="rgba(34,197,94,0.05)" stroke="rgba(34,197,94,0.15)" strokeWidth="1"/>
                  <path d="M10 14h36v24H10z" stroke="rgba(34,197,94,0.3)" strokeWidth="1.5" fill="none"/>
                  <circle cx="28" cy="26" r="6" stroke="rgba(34,197,94,0.3)" strokeWidth="1.5" fill="none"/>
                  <path d="M22 46h12" stroke="rgba(34,197,94,0.3)" strokeWidth="1.5" strokeLinecap="round"/>
                  <path d="M28 38v8" stroke="rgba(34,197,94,0.3)" strokeWidth="1.5" strokeLinecap="round"/>
                </svg>
              </div>
              <div style={{
                fontFamily: 'var(--font-mono)',
                fontSize: '11px',
                color: 'var(--text-muted)',
                letterSpacing: '3px',
                position: 'relative',
                zIndex: 1,
              }}>
                NO INPUT SIGNAL
              </div>
              <div style={{
                fontFamily: 'var(--font-mono)',
                fontSize: '9px',
                color: 'rgba(100,116,139,0.5)',
                letterSpacing: '2px',
                position: 'relative',
                zIndex: 1,
              }}>
                AWAITING SCREEN CAPTURE
              </div>
            </div>
          )}

          {/* Detection Boxes Overlay */}
          {isActive && showBoxes && (
            <div className="monitor-overlay">
              {DETECTION_BOXES.map(box => (
                <div
                  key={box.id}
                  className={`detection-box ${box.type === 'green' ? 'detection-box-green' : ''}`}
                  style={{
                    top: box.top,
                    left: box.left,
                    width: box.width,
                    height: box.height,
                  }}
                >
                  <div className={`detection-label ${box.type === 'green' ? 'detection-label-green' : ''}`}>
                    {box.label}
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* Scan line */}
          {isActive && (
            <div style={{
              position: 'absolute',
              top: `${scanLine}%`,
              left: 0,
              right: 0,
              height: '2px',
              background: 'linear-gradient(90deg, transparent, rgba(34,197,94,0.2), transparent)',
              pointerEvents: 'none',
              transition: 'top 0.02s linear',
            }} />
          )}

          {/* HUD Top */}
          <div className="monitor-hud-top">
            <span className="hud-cam-id">CAM-001 // SECTOR-A</span>
            {isActive && <span className="hud-fps">30 FPS</span>}
          </div>

          {/* HUD Bottom */}
          <div className="monitor-hud-bottom">
            <span className="hud-timestamp">{time}</span>
            {isActive && (
              <span style={{ fontFamily: 'var(--font-mono)', fontSize: '9px', color: 'rgba(255,255,255,0.4)' }}>
                AI PROC: ACTIVE
              </span>
            )}
          </div>
        </div>

        {/* Detection summary row */}
        {isActive && (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: '8px' }}>
            {[
              { label: 'Vehicles', value: '2', color: '#22c55e' },
              { label: 'No Plate', value: '1', color: '#ef4444' },
              { label: 'Confidence', value: '94%', color: '#06b6d4' },
            ].map(item => (
              <div key={item.label} style={{
                padding: '8px 12px',
                background: 'rgba(0,0,0,0.3)',
                border: '1px solid rgba(34,197,94,0.1)',
                borderRadius: '6px',
                textAlign: 'center',
              }}>
                <div style={{ fontFamily: 'var(--font-display)', fontSize: '18px', color: item.color, fontWeight: 700 }}>
                  {item.value}
                </div>
                <div style={{ fontFamily: 'var(--font-mono)', fontSize: '9px', color: 'var(--text-muted)', marginTop: '2px' }}>
                  {item.label}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
